    const rend2 = document.getElementById('v2-label-rend-2'); if (rend2) rend2.textContent = 'Mis Sitios';
    const rend3 = document.getElementById('v2-label-rend-3'); if (rend3) rend3.textContent = 'Mis Máquinas';
